---------------------------------------------------------------
--  CS2 压枪脚本 / CS2 Recoil Control Script
--  作者 / Author: Ethan
--
--  键盘 / Keyboard:
--    单击 G1 AK47             双击 G1 -
--    Single G1 AK47           Double G1 -
--    单击 G2 M4A1-S           双击 G2 M4A4
--    Single G2 M4A1-S         Double G2 M4A4
--    单击 G3 GALIL AR         双击 G3 FAMAS
--    Single G3 GALIL AR       Double G3 FAMAS
--    单击 G4 SG 553           双击 G4 AUG
--    Single G4 SG 553         Double G4 AUG
--    单击 G5 内格夫            双击 G5 M249
--    Single G5 Negev          Double G5 M249
--
--  鼠标 / Mouse:
--    侧键4 = 关闭所有 / Side 4 = Close all
--    侧键5 = SMG 通用 / Side 5 = SMG universal
---------------------------------------------------------------

---------------------------------------------------------------
-- 配置 / Configuration
---------------------------------------------------------------
-- 双击判定窗口(毫秒)，键盘与鼠标共用
-- Double-click window (ms), shared by keyboard and mouse
DOUBLE_WINDOW = 280

-- 按住此键时暂停压枪；设为 nil 关闭该功能
-- Hold this key to suspend recoil control; set nil to disable
SUSPEND_KEY   = "lalt"

-- 垂直强度，压过头调小，压不够调大
-- Vertical strength: lower if over-compensating, raise if under
SCALE_Y       = 1.00

-- 水平强度 / Horizontal strength
SCALE_X       = 1.00

-- 允许的时间轴落后(毫秒)，超出则重新对齐
-- Allowed timing drift (ms); resync beyond this
LAG_TOLERANCE = 20

-- true = 表走完停在原地，防止自动回正
-- true = hold position when table ends (prevents snap-back)
HOLD_AT_END   = true

-- 回弹补偿的细分次数，越大越平顺但更吃 CPU
-- Steps for recoil recovery; higher = smoother but heavier
round         = 40

-- 回弹速度 / Recovery speed
speed         = 2

-- 无线鼠标设 1，有线设 0
-- 1 = wireless mouse, 0 = wired
wireless      = 1

-- 切换时是否打印顶部标题
-- Print banner on weapon switch
OUTPUT_BANNER = true

-- SMG 表走完后是否继续补偿
-- Keep compensating after SMG curve ends
SMG_EXTEND    = true

-- SMG 循环起点（占曲线总长的比例）
-- Loop start point as a fraction of the curve
SMG_PLATEAU   = 0.75

-- SMG 整体强度 / SMG overall strength
SMG_GAIN      = 1.00

---------------------------------------------------------------
-- 键位映射 / Key Mapping
--
-- 值可以写 / Allowed values:
--   武器名   "ak47"   选中该武器 / select that weapon
--   weapon name        e.g. "ak47", "p90", "m249"
--   "smg"             SMG 通用档 / universal SMG mode
--   "off"             关闭所有 / close everything
--   nil               不响应 / ignore this key
--
-- 单击立即生效；DOUBLE_WINDOW 内再按一次触发 double。
-- Single press takes effect immediately; a second press within
-- DOUBLE_WINDOW triggers the `double` action.
---------------------------------------------------------------

-- 键盘 G 键 / Keyboard G-keys
KEYMAP = {
    [1] = { single = "ak47",  double = nil      },
    [2] = { single = "m4a1",  double = "m4a4"   },
    [3] = { single = "galil", double = "famas"  },
    [4] = { single = "sg553", double = "aug"    },
    [5] = { single = "negev", double = "m249"   },
}

-- 鼠标键 / Mouse buttons
--
-- 常见编号 / Common numbering:
--   1 = 左键 Left        2 = 中键 Middle     3 = 右键 Right
--   4 = 侧键 X1          5 = 侧键 X2
--   6 及以上因鼠标型号而异，必须实测
--   6+ varies by mouse model -- must be probed, do not guess
--
-- 想加更多键直接往表里加一项即可，键号没有上限：
-- To add more buttons just append an entry; there is no upper bound:
--   [6] = { single = "p90",  double = "cz75" },
--   [8] = { single = "mp9",  double = nil    },
--
-- 未在表里配置的键号会被静默忽略，不会报错。
-- Unmapped button numbers are silently ignored, no error.
--
-- 不知道自己的键号？用下面几行探测一次即可：
-- Don't know your button numbers? Probe once with this:
--   function OnEvent(event, arg)
--       if (event == "MOUSE_BUTTON_PRESSED") then
--           OutputLogMessage("mouse button = %d\n", arg)
--       end
--   end
-- 注：探测脚本会覆盖本脚本，测完记得换回正式脚本。
-- Note: the probe replaces this script; revert afterwards.
MOUSEMAP = {
    -- 侧键4：关闭所有 / Side button 4: close all
    [4] = { single = "off",  double = nil      },
    -- 侧键5：SMG 通用 / Side button 5: universal SMG
    [5] = { single = "smg",  double = nil      },
}

---------------------------------------------------------------
-- 压枪数据 / Recoil Data
--
-- 【当前启用 / Currently enabled】被上面两张映射表引用
--   Referenced by KEYMAP / MOUSEMAP above:
--   ak47   G1 单击 / single
--   m4a1   G2 单击 / single        m4a4   G2 双击 / double
--   galil  G3 单击 / single        famas  G3 双击 / double
--   sg553  G4 单击 / single        aug    G4 双击 / double
--   m249   G5 双击 / double
--   negev  G5 单击 / single
--
-- 【备用 / Standby】目前未被引用，想用就把名字填进 KEYMAP/MOUSEMAP
--   Not referenced yet; add the name to KEYMAP/MOUSEMAP to use:
--   p90  bizon  mp9  mac10  ump45  mp7  mp5sd
--        —— 7 把冲锋枪原始数据 / raw SMG data
--   cz75
--        —— CT 手枪 / CT pistol
--
-- 注意 / Note:
--   侧键5 的 "smg" 使用合成曲线，不直接引用这 7 张 SMG 表。
--   Side button 5's "smg" uses a composite curve and does NOT
--   reference the 7 raw SMG tables directly.
--   这 7 张原始数据保留下来，供你单独给某把 SMG 配键时使用。
--   Those 7 raw tables are kept so you can bind an individual SMG.
---------------------------------------------------------------

