---------------------------------------------------------------
-- 名字与查表 / Display names and lookup tables
---------------------------------------------------------------
DISPLAY = {
    ak47 = "AK47",  galil = "GALIL AR", m4a1 = "M4A1-S",
    m4a4 = "M4A4",  famas = "FAMAS",    aug  = "AUG",
    sg553 = "SG 553", m249 = "M249",    negev = "内格夫",
    p90 = "P90",    bizon = "BIZON",    mp9  = "MP9",
    mac10 = "MAC10", ump45 = "UMP45",   mp7  = "MP7",
    mp5sd = "MP5SD", cz75 = "CZ75",
}

-- 可被 SelectWeapon 选中的武器（全部 17 张表）
-- Weapons selectable via SelectWeapon (all 17 tables)
PATTERN = {
    ak47 = ak47, galil = galil, m4a1 = m4a1,
    m4a4 = m4a4, famas = famas, aug  = aug,
    sg553 = sg553, m249 = m249, negev = negev,
    p90 = p90, bizon = bizon, mp9 = mp9,
    mac10 = mac10, ump45 = ump45, mp7 = mp7,
    mp5sd = mp5sd, cz75 = cz75,
}

---------------------------------------------------------------
-- 状态 / State
---------------------------------------------------------------
activeWeapon = nil
inSMG        = false
indexPattern = 1
smgIdx       = 1
smgLoopFrom  = 1
flag2        = 1

backx,  backy   = 0, 0
backx1, backy1  = 0.00, 0.00
backx2, backy2  = 0, 0
backx3, backy3  = 0, 0
tsleep, tsleep3 = 0.00, 0.00
tsleep2   = 0
timestart = 0
accX, accY = 0.00, 0.00
lagCount  = 0
lastPress = {}

zz = {67,83,50,32,229,142,139,230,158,170,232,132,154,230,156,172,32,194,183,32,69,116,104,97,110,10,10,229,189,147,229,137,141,229,142,139,230,158,170,231,138,182,230,128,129,226,158,161}

---------------------------------------------------------------
-- 切枪 / Weapon switching
---------------------------------------------------------------
function ResetPattern()
    indexPattern = 1
    smgIdx       = 1
    backx,  backy  = 0, 0
    backx1, backy1 = 0.00, 0.00
    backx2, backy2 = 0, 0
    accX,   accY   = 0.00, 0.00
    tsleep3 = 0.00
    flag2   = 1
end

function Label()
    if (inSMG) then return "SMG 通用" end
    if (activeWeapon == nil) then return "已关闭" end
    return DISPLAY[activeWeapon] or activeWeapon
end

function Refresh()
    ClearLog()
    if (OUTPUT_BANNER) then Output(zz) end
    OutputLogMessage(Label() .. "\n")
end

---------------------------------------------------------------
-- 按键分派 / Key dispatch: shared by keyboard and mouse
---------------------------------------------------------------
function ApplyAction(a)
    if (a == nil) then return end
    if (a == "off") then
        CloseAll()
    elseif (a == "smg") then
        SelectSMG()
    else
        SelectWeapon(a)
    end
end

function HandlePress(key, map)
    if (map == nil) then return end

    local now  = GetRunningTime()
    local last = lastPress[key] or -100000
    local isDouble = (now - last <= DOUBLE_WINDOW)

    if (isDouble and map.double ~= nil) then
        -- 清计时，避免三连击被当成又一次双击
        -- clear timer so a triple press is not read as another double
        lastPress[key] = -100000
        ApplyAction(map.double)
    else
        lastPress[key] = now
        ApplyAction(map.single)
    end
end

function SelectWeapon(name)
    if (name == nil or PATTERN[name] == nil) then
        Refresh()
        OutputLogMessage("（" .. (DISPLAY[name] or tostring(name)) ..
                         " 数据缺失，未启用）\n")
        return
    end
    inSMG        = false
    activeWeapon = name
    ResetPattern()
    Refresh()
end

function SelectSMG()
    inSMG        = true
    activeWeapon = nil
    smgLoopFrom  = math.floor(#SMG_CURVE * SMG_PLATEAU)
    if (smgLoopFrom < 1) then smgLoopFrom = 1 end
    ResetPattern()
    Refresh()
end

function CloseAll()
    inSMG        = false
    activeWeapon = nil
    ResetPattern()
    Refresh()
end

---------------------------------------------------------------
-- 取点 / Fetch compensation point
---------------------------------------------------------------
function SMGGetPoint(idx)
    local n = #SMG_CURVE
    if (idx > n) then
        if (not SMG_EXTEND) then return nil end
        idx = smgLoopFrom + ((idx - n - 1) % (n - smgLoopFrom + 1))
    end
    if (idx < 1) then idx = 1 end
    if (idx > n) then idx = n end
    local p = SMG_CURVE[idx]
    return p.x * SMG_GAIN, p.y * SMG_GAIN, p.d
end

---------------------------------------------------------------
-- 事件 / Events
---------------------------------------------------------------
EnablePrimaryMouseButtonEvents(true)

function OnEvent(event, arg)
    if (wireless == 1) then Sleep(1) end

    if (event == "G_PRESSED" and arg ~= nil) then
        HandlePress("k" .. arg, KEYMAP[arg])
    end

    if (event == "MOUSE_BUTTON_PRESSED" and arg ~= nil) then
        HandlePress("m" .. arg, MOUSEMAP[arg])
    end

    while IsMouseButtonPressed(1) and flag2 == 1 do

        local active = inSMG or (activeWeapon ~= nil and PATTERN[activeWeapon] ~= nil)

        if (active and (SUSPEND_KEY == nil or not IsModifierPressed(SUSPEND_KEY))) then

            local px, py, pd

            if (inSMG) then
                px, py, pd = SMGGetPoint(smgIdx)
            else
                local pat = PATTERN[activeWeapon]
                if (indexPattern < #pat) then
                    local p = pat[indexPattern]
                    px, py, pd = p.x, p.y, p.d
                else
                    px = nil
                end
            end

            if (px ~= nil) then
                if ((not inSMG and indexPattern == 1) or (inSMG and smgIdx == 1)) then
                    timestart = GetRunningTime()
                    accX, accY = 0.00, 0.00
                    lagCount = 0
                end

                accX = accX + px * SCALE_X
                accY = accY + py * SCALE_Y
                local mx = math.floor(accX + 0.5)
                local my = math.floor(accY + 0.5)
                accX = accX - mx
                accY = accY - my

                if (mx ~= 0 or my ~= 0) then MoveMouseRelative(mx, my) end
                backx = backx - mx
                backy = backy - my

                timestart = timestart + pd
                local now = GetRunningTime()
                if (now - timestart > LAG_TOLERANCE) then
                    timestart = now
                    lagCount = lagCount + 1
                end
                Sleep3(timestart)

                if (inSMG) then smgIdx = smgIdx + 1
                else indexPattern = indexPattern + 1 end
            else
                if (HOLD_AT_END) then
                    flag2 = 0
                    Sleep(50)
                else
                    backx2 = math.floor(backx / 40)
                    backy2 = math.floor(backy / 40)
                    i = 0
                    while (i < round) do
                        tsleep  = 2 * math.sqrt(math.abs(backx) * math.abs(backx)
                                              + math.abs(backy) * math.abs(backy)) / round / speed
                        tsleep2 = math.floor(tsleep)
                        tsleep3 = tsleep3 + tsleep - tsleep2
                        if (tsleep3 >= 1) then
                            tsleep3 = tsleep3 - 1; tsleep2 = tsleep2 + 1
                        end
                        Sleep2(tsleep2)
                        backx1 = backx1 + backx / 40 - backx2
                        backy1 = backy1 + backy / 40 - backy2
                        if (backx1 >= 1) then backx1 = backx1 - 1; backx3 = backx2 + 1
                        else backx3 = backx2 end
                        if (backy1 >= 1) then backy1 = backy1 - 1; backy3 = backy2 + 1
                        else backy3 = backy2 end
                        MoveMouseRelative(backx3, backy3)
                        i = i + 1
                    end
                    ResetPattern()
                    flag2 = 0
                    Sleep(1000)
                end
            end
        end
    end

    if (event == "MOUSE_BUTTON_RELEASED" and arg == 1
        and (inSMG or (activeWeapon ~= nil and PATTERN[activeWeapon] ~= nil))) then
        backx2 = math.floor(backx / 40)
        backy2 = math.floor(backy / 40)
        i = 0
        while (i < round and (backx2 ~= 0 or backy2 ~= 0)) do
            tsleep  = (150 + 1.1 * math.sqrt(math.abs(backx) * math.abs(backx)
                                           + math.abs(backy) * math.abs(backy))) / round / speed
            tsleep2 = math.floor(tsleep)
            tsleep3 = tsleep3 + tsleep - tsleep2
            if (tsleep3 >= 1) then
                tsleep3 = tsleep3 - 1; tsleep2 = tsleep2 + 1
            end
            Sleep2(tsleep2)
            backx1 = backx1 + backx / 40 - backx2
            backy1 = backy1 + backy / 40 - backy2
            if (backx1 >= 1) then backx1 = backx1 - 1.00; backx3 = backx2 + 1
            else backx3 = backx2 end
            if (backy1 >= 1) then backy1 = backy1 - 1.00; backy3 = backy2 + 1
            else backy3 = backy2 end
            MoveMouseRelative(backx3, backy3)
            i = i + 1
        end
        ResetPattern()
    end
end

---------------------------------------------------------------
-- 工具 / Utility
---------------------------------------------------------------
function Sleep2(time)
    local start = GetRunningTime()
    while (time + start > GetRunningTime()) do end
end

function Sleep3(time)
    while (time > GetRunningTime()) do end
end

function Output(bytes)
    local b = ""
    for i = 1, #bytes do b = b .. string.char(bytes[i]) end
    OutputLogMessage(b)
end
